  {"code":"38.1","room_id":38,"schema":{"measurement_type":"ratio","indicator_direction":"positive","metadata_reconciliation_source":"PMKP 2026: master tahunan dan instrumen unit"},"patch":{}}
]$plan$;
  matched integer;
BEGIN
  SELECT count(*) INTO matched
  FROM aureka_quality.indicator_profiles p
  JOIN jsonb_to_recordset(profiles) AS r(code text,room_id bigint) USING(code,room_id)
  WHERE p.profile_year=2026 AND p.is_active AND p.status='published';
  IF matched<>64 THEN
    RAISE EXCEPTION 'Expected 64 active 2026 profiles, found %',matched;
  END IF;

  UPDATE aureka_quality.indicator_profiles p SET
    schema_json=p.schema_json || r.schema,
    numerator_definition=coalesce(r.patch->>'numerator_definition',p.numerator_definition),
    denominator_definition=coalesce(r.patch->>'denominator_definition',p.denominator_definition),
    target_text=coalesce(r.patch->>'target_text',p.target_text),
    target_operator=coalesce(r.patch->>'target_operator',p.target_operator),
    target_value=CASE WHEN r.patch ? 'target_value' THEN (r.patch->>'target_value')::numeric ELSE p.target_value END,
    options_json=coalesce(r.patch->'options_json',p.options_json),
    updated_at=now()
  FROM jsonb_to_recordset(profiles) AS r(code text,room_id bigint,schema jsonb,patch jsonb)
  WHERE p.code=r.code AND p.room_id=r.room_id AND p.profile_year=2026 AND p.is_active AND p.status='published'
    AND NOT (p.schema_json ? 'metadata_reconciliation_source');

  -- Recover only pending responses whose retained source text and code agree.
  WITH source_candidates AS (
    SELECT rr.id,qr.id AS record_id,p.code,
      CASE p.code WHEN '9.1' THEN 'Darah Terpakai'
                  ELSE 'Pasien Dirawat Dengan Kendala Penunjang Lainnya' END AS label,
      CASE p.code WHEN '9.1' THEN 1 ELSE 3 END AS response_code,
      CASE p.code WHEN '9.1' THEN qr.core_data->'source_import'->'source_indicator_values'->>'9.1'
                  ELSE rr.raw_value->>'source_value' END AS source_value
    FROM aureka_quality.quality_record_responses rr
    JOIN aureka_quality.indicator_profiles p ON p.id=rr.indicator_id
    JOIN aureka_quality.quality_records qr ON qr.id=rr.record_id AND qr.room_id=p.room_id
    WHERE p.profile_year=2026 AND p.status='published' AND p.is_active
      AND qr.profile_year=2026 AND qr.status IN ('ready','validated')
      AND rr.review_status='pending' AND rr.response_code IS NULL
      AND (
        (p.code='9.1' AND p.room_id=9
          AND qr.core_data->'source_import'->>'source_workbook'='PMKP - Instalasi Laboratorium - 2026.xlsx'
          AND qr.core_data->'source_import'->'source_indicator_values'->>'9.1'='Darah Terpakai (Code 1)')
        OR (p.code='14.1' AND p.room_id=14
          AND rr.response_label='Pasien Dirawat Dengan Kendala Penunjang Lainnya'
          AND rr.raw_value->>'source_code'='3'
          AND rr.raw_value->>'mapping_status' IN ('source_master_conflict','master_pending'))
      )
  ), corrected AS (
    UPDATE aureka_quality.quality_record_responses rr SET
      response_code=c.response_code,response_label=c.label,review_status='not_required',
      raw_value=coalesce(rr.raw_value,'{}'::jsonb) || jsonb_build_object(
        'answer',c.label,'code',c.response_code,'source_code',c.response_code,
        'source_value',c.source_value,'mapping_status','mapped',
        'review_required',false,'source_option',false,'review_status','not_required',
        'correction_source','PMKP 2026 / verified retained source'),
      updated_at=now()
    FROM source_candidates c
    WHERE rr.id=c.id AND rr.review_status='pending'
      AND EXISTS (
        SELECT 1 FROM aureka_quality.indicator_profiles p, jsonb_array_elements(p.options_json) AS x(option)
        WHERE p.id=rr.indicator_id AND option->>'label'=c.label AND option->>'code'=c.response_code::text
      )
    RETURNING rr.record_id,c.code,rr.raw_value
  )
  UPDATE aureka_quality.quality_records qr SET
    core_data=jsonb_set(qr.core_data,'{indicator_values}',coalesce(qr.core_data->'indicator_values','{}'::jsonb) ||
      jsonb_build_object(c.code,c.raw_value),true),updated_at=now()
  FROM corrected c WHERE qr.id=c.record_id;
END
$profile_repair$;
